    if (t <= pairs[0][0]) return pairs[0][1];
    const last = pairs[pairs.length - 1];
    if (t >= last[0]) return last[1];
    let i = 0;
    while (i < pairs.length - 2 && t > pairs[i + 1][0]) i++;
